INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 3, 'theory', 'Quiz: standards and open architectures');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 0, 'What is needed for the output of one gate to reliably drive the input of another?', '["Identical family names", "Identical wire lengths", "Both gates on the same die", "The driver''s VOH above the receiver''s VIH and VOL below VIL"]', 3, 'Only if the driver''s output levels fall within the receiver''s “allowed” input ranges will noise not break operation. That is why logic families are described by their levels.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 1, 'What happens if a 5 V signal is applied to the input of a chip rated for 3.3 V without 5 V tolerance?', '["Nothing: more voltage is more reliable", "The input may be damaged", "The signal becomes a zero", "The chip automatically lowers the voltage"]', 1, 'The input transistors are designed for a lower voltage. Chip datasheets always state whether five-volt signals are allowed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 2, 'What is an ISA?', '["A set of instructions, registers, and rules for working with memory: a contract between the program and the processor", "A type of memory chip", "The name of an operating system", "A data bus"]', 0, 'The Instruction Set Architecture fixes what the programmer sees. The implementation, the microarchitecture, can differ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 3, 'How does RISC-V differ from x86 and ARM?', '["It runs only on five cores", "It does not support multiplication", "Its specification is open: processors can be built and changed without paying license fees to an owner", "It exists only as an emulator"]', 2, 'RISC-V is maintained by an open organization, RISC-V International: the specification is free for everyone, and extensions can be added without breaking compatibility.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 3, 4, 'What does the name RV32IMAC mean?', '["A processor with 32 cores", "A 32-bit RISC-V with the base set I and the extensions M (multiplication), A (atomics), and C (compressed instructions)", "Four separate processors", "Version 32 of the standard"]', 1, 'Modularity: standard extensions are added to the base, and the manufacturer picks the ones it needs. The extensions M, A, F, D, C are listed in the name.');
